def transform(grid):
    """Overlay the nonzero masks across the central divider."""
    h, w = len(grid), len(grid[0])

    # Horizontal divider: intersect the corresponding rows above and below.
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            top, bottom = grid[:r], grid[r + 1:]
            return [[2 if a != 0 and b != 0 else 0 for a, b in zip(top_row, bottom_row)]
                    for top_row, bottom_row in zip(top, bottom)]

    # Vertical divider: intersect cells at the same local column on both sides.
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid) and c == w - c - 1:
            return [[2 if row[j] != 0 and row[c + 1 + j] != 0 else 0
                     for j in range(c)] for row in grid]

    raise ValueError('No central divider with equal panels')

def transform(grid):
    """Intersect the two masks separated by a central horizontal divider."""
    h = len(grid)
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            top, bottom = grid[:r], grid[r + 1:]
            return [[2 if a != 0 and b != 0 else 0 for a, b in zip(top_row, bottom_row)]
                    for top_row, bottom_row in zip(top, bottom)]
    raise ValueError('No central horizontal divider')
